#include "Events.h"
#include "Storage.h"
#include "Settings.h"
namespace Events {
struct LegacyEvent{uint32_t magic=0x52564532,id=0,epoch=0,uptime=0;char photo[29]={},video[29]={},note[64]={};uint8_t ready=0;uint8_t padding[1]={};uint32_t checksum=0;};
struct Event{uint32_t magic=0x52564533,id=0,epoch=0,uptime=0;char photo[29]={},video[29]={},note[64]={},camera[49]={},delivery[24]="disabled";uint8_t ready=0,score=0;uint32_t checksum=0;};
static uint32_t reserved=0;
static constexpr unsigned LIMIT=32;static Event events[LIMIT];static uint32_t next=0;static SemaphoreHandle_t mutex;
static uint32_t checksum(const Event&e){uint32_t h=2166136261;const uint8_t*p=(const uint8_t*)&e;for(size_t i=0;i<offsetof(Event,checksum);i++)h=(h^p[i])*16777619;return h;}
static void persist(Event e,bool owned){
 if(!Storage::available)return;bool lock=owned||xSemaphoreTake(Storage::operationMutex,0)==pdTRUE;if(!lock)return;e.checksum=checksum(e);
 File f=SD_MMC.open("/robetix/events-v3.bin",SD_MMC.exists("/robetix/events-v3.bin")?"r+":"w+");if(f){if(f.seek((e.id%LIMIT)*sizeof(Event)))f.write((uint8_t*)&e,sizeof(e));f.flush();f.close();}if(!owned)xSemaphoreGive(Storage::operationMutex);
}
void begin(){mutex=xSemaphoreCreateMutex();next=prefs.getUInt("eventSeq",0);if(!mutex||!Storage::available)return;File f=SD_MMC.open("/robetix/events-v3.bin");if(!f){File old=SD_MMC.open("/robetix/events.bin");for(unsigned i=0;old&&i<LIMIT;i++){LegacyEvent legacy;if(old.read((uint8_t*)&legacy,sizeof(legacy))!=sizeof(legacy))break;uint32_t hash=2166136261;for(size_t b=0;b<offsetof(LegacyEvent,checksum);b++)hash=(hash^((uint8_t*)&legacy)[b])*16777619;if(legacy.magic!=0x52564532||legacy.checksum!=hash||!legacy.id||legacy.photo[28]||legacy.video[28]||legacy.note[63])continue;Event e;e.id=legacy.id;e.epoch=legacy.epoch;e.uptime=legacy.uptime;e.ready=legacy.ready;memcpy(e.photo,legacy.photo,29);memcpy(e.video,legacy.video,29);memcpy(e.note,legacy.note,64);strlcpy(e.camera,"Earlier event",49);events[e.id%LIMIT]=e;next=max(next,e.id);}old.close();next=max(next,prefs.getUInt("eventSeq",0));return;}for(unsigned i=0;i<LIMIT;i++){Event e;if(f.read((uint8_t*)&e,sizeof(e))!=sizeof(e))break;if(e.magic==0x52564533&&e.id&&e.checksum==checksum(e)&&e.photo[28]==0&&e.video[28]==0&&e.note[63]==0&&e.camera[48]==0&&e.delivery[23]==0){events[e.id%LIMIT]=e;next=max(next,e.id);}}f.close();next=max(next,prefs.getUInt("eventSeq",0));}
uint32_t add(uint32_t epoch,const String&photo,const String&video,const char*note,bool owned,const char*camera,uint8_t score){if(!mutex)return 0;Event e;e.epoch=epoch;e.uptime=millis()/1000;strlcpy(e.photo,photo.c_str(),sizeof(e.photo));strlcpy(e.video,video.c_str(),sizeof(e.video));strlcpy(e.note,note,sizeof(e.note));xSemaphoreTake(mutex,portMAX_DELAY);if(next>=reserved){reserved=next+32;if(reserved<next||!prefs.putUInt("eventSeq",reserved)){xSemaphoreGive(mutex);return 0;}}e.id=++next;strlcpy(e.camera,camera,sizeof(e.camera));e.score=score;events[e.id%LIMIT]=e;xSemaphoreGive(mutex);persist(e,owned);return e.id;}
void delivery(uint32_t id,const char*state){if(!mutex||!id)return;xSemaphoreTake(mutex,portMAX_DELAY);Event&e=events[id%LIMIT];if(e.id==id)strlcpy(e.delivery,state,sizeof(e.delivery));xSemaphoreGive(mutex);}
void attach(uint32_t id,const String&video,bool owned){if(!mutex||!id)return;xSemaphoreTake(mutex,portMAX_DELAY);Event e=events[id%LIMIT];if(e.id==id){strlcpy(e.video,video.c_str(),sizeof(e.video));events[id%LIMIT]=e;}xSemaphoreGive(mutex);if(e.id==id)persist(e,owned);}
void complete(const String&video,bool ok,bool owned){if(!mutex)return;for(unsigned i=0;i<LIMIT;i++){xSemaphoreTake(mutex,portMAX_DELAY);Event e=events[i];bool match=e.id&&video==e.video;if(match){e.ready=ok?1:0;strlcpy(e.note,ok?"Movement detected":"Movement detected; video save failed",sizeof(e.note));events[i]=e;}xSemaphoreGive(mutex);if(match)persist(e,owned);}}
uint32_t latest(){if(!mutex)return 0;xSemaphoreTake(mutex,portMAX_DELAY);uint32_t id=0;for(const auto&e:events)id=max(id,e.id);xSemaphoreGive(mutex);return id;}
void list(JsonObject o){auto a=o.createNestedArray("events");if(!mutex)return;xSemaphoreTake(mutex,portMAX_DELAY);uint32_t cursor=UINT32_MAX;for(unsigned n=0;n<12;n++){Event*found=nullptr;for(auto&candidate:events)if(candidate.id&&candidate.id<cursor&&(!found||candidate.id>found->id))found=&candidate;if(!found)break;Event&e=*found;cursor=e.id;auto row=a.createNestedObject();row["id"]=e.id;row["epoch"]=e.epoch;row["uptime"]=e.uptime;row["photo"]=e.photo;row["video"]=e.video;row["video_ready"]=bool(e.ready);row["note"]=e.note;row["camera"]=e.camera;row["score"]=e.score;row["notification"]=e.delivery;}xSemaphoreGive(mutex);}
}
